found = []
for s in d['slack']:
    msg = json.dumps(s).lower()
    if any(k in msg for k in keywords):
        found.append(s)

print(f"Found {len(found)} slack messages")
for s in found[:50]:
    user = s['Message']['User']
    print(s['id'], '|user:', user['userId'], '|ch:', s['Channel']['name'])
    print('  text:', user['text'][:300])
    for r in s.get('ThreadReplies',[]) or []:
        ru = r.get('User',{}) if isinstance(r,dict) else {}
        if ru:
            print('   reply by', ru.get('userId'), ':', ru.get('text','')[:200])
    print()
EOF
